const THRESHOLD = 128; // 0–255

api.forEach((r, g, b, a) => {
  const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  const v = lum >= THRESHOLD ? 255 : 0;
  return [v, v, v, a];
});
api.log('Threshold applied at ' + THRESHOLD);
